509	// 等待期间绑定授权被撤回或患者档案被停用：核对时按最新状态拒绝；即使存在
510	// 另一条同患者、同接收方、覆盖相同记录且仍有效的授权也不能替代，交付为空。
511	func TestFetchPackageWaitHitsRevocationAndDeactivation(t *testing.T) {
512		f := setupExchange(t)
513		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-wait-rev")
514		if err != nil {
515			t.Fatal(err)
516		}
517		otherAuth, err := f.s.Grant(doc, f.pid, rcv.ID,
518			[]Scope{{EncounterID: f.e1, Category: Diagnosis}}, f.start, f.end.Add(24*time.Hour))
519		if err != nil {
520			t.Fatal(err)
521		}
522		_ = otherAuth
523	
524		// 请求发出时绑定授权仍有效；等待期间（由先完成的其他操作）撤回，
525		// 本次核对开始时它已撤回：拒绝且交付为空。
526		f.s.mu.Lock()
527		del, err := fetchWhileStoreBusyLocked(f.s, func(snap *snapshot, now time.Time) {
528			if a := snap.Authorizations[f.auth.ID]; a != nil {
529				revoked := now
530				a.RevokedAt = &revoked
531			}
532		}, rcv, x.ID)
533		if !errors.Is(err, ErrAccessDenied) {
534			t.Fatalf("binding revoked during wait: err = %v, want ErrAccessDenied", err)
535		}
536		if !emptyDelivery(del) {
537			t.Fatalf("denied delivery must carry no exchange info: %+v", del)
538		}
539	
540		// 第二份交换：等待期间患者档案被停用，核对时必须拒绝。
541		orderAuth, err := f.s.Grant(doc, f.pid, rcv.ID,
542			[]Scope{{EncounterID: f.e1, Category: Order}}, f.start, f.end.Add(24*time.Hour))
543		if err != nil {
544			t.Fatal(err)
545		}
546		x2, err := f.s.CreateExchange(doc, f.pid, rcv.ID, orderAuth.ID, []ID{f.ord}, "req-wait-deact")
547		if err != nil {
548			t.Fatal(err)
549		}
550		f.s.mu.Lock()
551		del2, err := fetchWhileStoreBusyLocked(f.s, func(snap *snapshot, now time.Time) {
552			if p := snap.Patients[f.pid]; p != nil {
553				p.Deactivated = true
554			}
555		}, rcv, x2.ID)
556		if !errors.Is(err, ErrAccessDenied) {
557			t.Fatalf("patient deactivated during wait: err = %v, want ErrAccessDenied", err)
558		}
559		if !emptyDelivery(del2) {
560			t.Fatalf("denied delivery must carry no exchange info: %+v", del2)
561		}
562	}
