896		if got.Status != ExchangeRejected || got.Receipt == nil || got.Receipt.Reason != "重开前拒绝" {
897			t.Fatalf("receipt lost: %+v", got)
898		}
899		if len(got.Package.Records) != 1 || got.Package.Records[0].VersionID != v1.ID ||
900			got.Package.Records[0].Content != "包内v1" {
901			t.Fatalf("frozen package lost: %+v", got.Package.Records)
902		}
903	
904		// 同请求号重试仍返回原交换，不新增审计。
905		auditBefore := len(mustAudit(t, s2, p.ID))
906		retry, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
907		if err != nil {
908			t.Fatalf("retry after reopen: %v", err)
909		}
910		if retry.ID != x.ID || retry.Status != ExchangeRejected {
911			t.Fatalf("retry after reopen = %+v", retry)
912		}
913		if retry.Package.Records[0].Content != "包内v1" {
914			t.Fatalf("retry refetched current content: %+v", retry.Package.Records)
915		}
916		if n := len(mustAudit(t, s2, p.ID)); n != auditBefore {
917			t.Fatalf("retry after reopen added audit: %d", n)
918		}
919	
920		// 审计两类事件都在。
921		var creates, receipts int
922		for _, ev := range mustAudit(t, s2, p.ID) {
923			switch ev.Action {
924			case ActionExchanged:
925				creates++
926			case ActionReceipted:
927				receipts++
928			}
929		}
930		if creates != 1 || receipts != 1 {
931			t.Fatalf("audit after reopen: creates=%d receipts=%d", creates, receipts)
932		}
933	
934		// 取包路径在重开后同样按当前时间与绑定授权判断（窗口内可取）。
935		del, err := s2.FetchPackage(rcv, x.ID)
936		if err != nil {
937			t.Fatalf("fetch after reopen: %v", err)
938		}
939		if del.Digest != x.Digest || del.Status != ExchangeRejected {
940			t.Fatalf("delivery after reopen wrong: %+v", del)
941		}
942	}
943	
944	// 关闭后调用返回 ErrClosed。
945	func TestExchangeOperationsAfterClose(t *testing.T) {
946		f := setupExchange(t)
947		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-closed")
948		if err != nil {
949			t.Fatal(err)
950		}
951		if err := f.s.Close(); err != nil {
952			t.Fatal(err)
953		}
954		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-closed-2"); !errors.Is(err, ErrClosed) {
955			t.Fatalf("create after close err = %v", err)
956		}
957		if _, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrClosed) {
958			t.Fatalf("fetch after close err = %v", err)
959		}
960		if _, err := f.s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, ""); !errors.Is(err, ErrClosed) {
961			t.Fatalf("receipt after close err = %v", err)
962		}
963		if _, err := f.s.GetExchange(doc, f.pid, x.ID); !errors.Is(err, ErrClosed) {
964			t.Fatalf("get after close err = %v", err)
965		}
966	}
