520			t.Fatalf("local receipt tamper changed audit count: before=%d after=%d", auditBefore, got)
521		}
522	}
523	
524	// ---- 待回执交换：在手中结果里补造假回执，重新查询仍没有回执 ----
525	
526	func TestFabricatedReceiptOnPendingExchangeDoesNotPersist(t *testing.T) {
527		f := setupExchange(t)
528		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
529			[]ID{f.diag, f.ord}, "req-iso-noreceipt")
530		if err != nil {
531			t.Fatal(err)
532		}
533	
534		g, err := f.s.GetExchange(doc, f.pid, x.ID)
535		if err != nil {
536			t.Fatal(err)
537		}
538		if g.Status != ExchangePending || g.Receipt != nil {
539			t.Fatalf("new exchange should have no receipt: %+v", g)
540		}
541	
542		// 调用方在手中的结果里补上回执信息。
543		g.Status = ExchangeRejected
544		g.Receipt = &Receipt{
545			Outcome:      ReceiptRejected,
546			Reason:       "手中补造的拒绝",
547			RegisteredAt: time.Date(2003, 5, 6, 7, 8, 9, 0, time.UTC),
548		}
549	
550		// 重新查询：仍无回执、仍待回执。
551		g2, err := f.s.GetExchange(doc, f.pid, x.ID)
552		if err != nil {
553			t.Fatal(err)
554		}
555		if g2.Status != ExchangePending || g2.Receipt != nil {
556			t.Fatalf("fabricated receipt leaked into store: %+v", g2)
557		}
558	
559		// 列表结果中补造假回执同样无效。
560		lst, err := f.s.ListExchanges(doc, f.pid)
561		if err != nil {
562			t.Fatal(err)
563		}
564		if len(lst) != 1 || lst[0].Receipt != nil || lst[0].Status != ExchangePending {
565			t.Fatalf("list reflects fabricated receipt: %+v", lst)
566		}
567		lst[0].Status = ExchangeAccepted
568		lst[0].Receipt = &Receipt{Outcome: ReceiptAccepted, RegisteredAt: time.Now()}
569	
570		g3, _ := f.s.GetExchange(doc, f.pid, x.ID)
571		if g3.Status != ExchangePending || g3.Receipt != nil {
572			t.Fatalf("fabricated receipt via list leaked into store: %+v", g3)
573		}
574	
575		// 接收方取包看到的仍是待回执。
576		d, err := f.s.FetchPackage(rcv, x.ID)
577		if err != nil {
578			t.Fatal(err)
579		}
580		if d.Status != ExchangePending {
581			t.Fatalf("delivery status = %q, want %q", d.Status, ExchangePending)
582		}
583	
584		// 自始至终没有任何回执审计。
585		if c := receiptAuditCount(t, f.s, f.pid); c != 0 {
586			t.Fatalf("receipt audits = %d, want 0", c)
587		}
588	}
589	
590	// ---- 端到端：从各入口取得并篡改的结果，即使触发一次真实原子写盘并重开，
591	//      库内交换、摘要、回执与审计仍保持原样 ----
592	
593	func TestLocalMutationsDoNotPersistAcrossReopen(t *testing.T) {
594		dir := t.TempDir()
595		clk := &fakeClock{t: time.Date(2026, 3, 1, 9, 0, 0, 0, time.UTC)}
596		open := func() *Store {
