626		}
627		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
628			[]ID{recD.ID, recO.ID}, "req-reopen-iso")
629		if err != nil {
630			t.Fatal(err)
631		}
632		want := snapshotExchange(x)
633	
634		// 从每一个返回入口取得结果并全部在本地篡改。
635		g, err := s.GetExchange(doc, p.ID, x.ID)
636		if err != nil {
637			t.Fatal(err)
638		}
639		tamperExchangeResult(&g)
640	
641		lst, err := s.ListExchanges(doc, p.ID)
642		if err != nil {
643			t.Fatal(err)
644		}
645		tamperExchangeResult(&lst[0])
646	
647		retry, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
648			[]ID{recO.ID, recD.ID}, "req-reopen-iso")
649		if err != nil {
650			t.Fatal(err)
651		}
652		tamperExchangeResult(&retry)
653	
654		d, err := s.FetchPackage(rcv, x.ID)
655		if err != nil {
656			t.Fatal(err)
657		}
658		tamperDeliveryResult(&d)
659	
660		// 触发一次真实的整体原子写盘：对医嘱记录做一次合法更正（幂等重试只是
661		// 读取已保存的结果，本身不再落盘）。更正不改写已创建交换的冻结包。
662		if _, err := s.CorrectRecord(doc, recO.ID, 1, "医嘱内容-更正版", "触发一次真实落盘"); err != nil {
663			t.Fatalf("correction that forces persist: %v", err)
664		}
665		again, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
666			[]ID{recD.ID, recO.ID}, "req-reopen-iso")
667		if err != nil {
668			t.Fatalf("retry after persist: %v", err)
669		}
670		assertExchangeMatches(t, again, want, "retry after persist still returns original")
671	
