19	//     撤回时间仍是首次成功撤回的时间，审计中该授权的撤回事件仍只有首次
20	//     那一条，事件身份与时间不被确认者替换；
21	//   - 接收方不能撤回；引用不存在的授权、把其他患者的授权用于当前患者，
22	//     仍按原来的明确错误失败——“已撤回”不构成这些请求成功的理由，这些
23	//     校验失败也不需要写盘；
24	//   - 另一条尚未撤回的合法授权在保存不可用时首次撤回：必须明确返回保存
25	//     错误，不能报告成功；授权保持未撤回、读取与取包不被提前禁止、不新增
26	//     撤回事件。保存恢复后重新提交才真正撤回，记录这次实际成功的时间与
27	//     身份，此前失败的尝试不作为成功依据。
28	func TestRepeatRevokeConfirmsWithoutSave(t *testing.T) {
29		dir := t.TempDir()
30		clk := &fakeClock{t: time.Date(2026, 7, 1, 9, 0, 0, 0, time.UTC)}
31		open := func() *Store {
32			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
33			if err != nil {
34				t.Fatalf("open: %v", err)
35			}
36			return s
37		}
38	
39		s := open()
40		t.Cleanup(func() { _ = s.Close() })
41	
42		p, err := s.RegisterPatient(doc, "重复撤回确认患者")
43		if err != nil {
44			t.Fatal(err)
45		}
46		p2, err := s.RegisterPatient(doc, "重复撤回其他患者")
47		if err != nil {
48			t.Fatal(err)
49		}
50		e, err := s.AddEncounter(doc, p.ID, time.Time{})
51		if err != nil {
52			t.Fatal(err)
53		}
54		activate := func(content string) ID {
55			t.Helper()
56			r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, content)
57			if err != nil {
58				t.Fatal(err)
59			}
60			if _, err := s.ActivateRecord(doc, r.ID); err != nil {
61				t.Fatal(err)
62			}
63			return r.ID
64		}
65		d1 := activate("诊断一内容")
66		d2 := activate("诊断二内容")
67	
68		start := clk.t.Add(-time.Hour)
69		end := clk.t.Add(48 * time.Hour)
70		// a1：整类覆盖全部诊断，准备首次撤回；a2：限定授权，只选出 d1，
71		// 保存不可用期间保持有效，用于证明其他授权独立生效、失败尝试不提前禁权。
72		a1, err := s.Grant(doc, p.ID, rcv.ID,
73			[]Scope{{EncounterID: e.ID, Category: Diagnosis}}, start, end)
74		if err != nil {
75			t.Fatal(err)
76		}
77		a2, err := s.GrantSelective(doc, p.ID, rcv.ID, nil,
78			[]RecordSelection{sel(e.ID, Diagnosis, d1)}, start, end)
79		if err != nil {
80			t.Fatal(err)
81		}
82		// 一份绑定 a1 的待回执交换，用于观察撤回与失败尝试对取包的影响。
83		exch, err := s.CreateExchange(doc, p.ID, rcv.ID, a1.ID, []ID{d1, d2}, "req-repeat-revoke")
84		if err != nil {
85			t.Fatal(err)
86		}
87	
88		// ---- 首次成功撤回：完整保存授权变化与审计 ----
89		firstRevokeAt := clk.t.Add(time.Hour)
90		clk.t = firstRevokeAt
91		if err := s.Revoke(doc, p.ID, a1.ID); err != nil {
92			t.Fatalf("first revoke: %v", err)
93		}
94		first, err := s.GetAuthorization(doc, p.ID, a1.ID)
95		if err != nil {
96			t.Fatal(err)
97		}
98		if first.RevokedAt == nil || !first.RevokedAt.Equal(firstRevokeAt) {
99			t.Fatalf("first revocation time = %v, want %v", first.RevokedAt, firstRevokeAt)
100		}
101		auditAfterFirst, err := s.AuditEvents(doc, p.ID)
102		if err != nil {
103			t.Fatal(err)
104		}
105		if got := auditActions(auditAfterFirst)[ActionRevoked]; got != 1 {
106			t.Fatalf("revoke events after first revoke = %d, want 1", got)
107		}
108		firstScope := append([]Scope(nil), first.Scopes...)
109		firstSels := append([]RecordSelection(nil), first.Selections...)
110	
111		// ---- 令本地保存条件暂时不可用：数据文件原位置被同名目录占据 ----
112		dataPath := filepath.Join(dir, dataName)
113		backupPath := dataPath + ".saved"
114		if err := os.Rename(dataPath, backupPath); err != nil {
115			t.Fatalf("backup data file: %v", err)
116		}
117		if err := os.Mkdir(dataPath, 0o755); err != nil {
118			t.Fatalf("block data path: %v", err)
119		}
120		t.Cleanup(func() { _ = os.RemoveAll(dataPath) })
121	
122		// 原内部使用者重复撤回：必须成功，不依赖当前能否写入本地数据。
123		later := clk.t.Add(2 * time.Hour)
124		clk.t = later
125		if err := s.Revoke(doc, p.ID, a1.ID); err != nil {
126			t.Fatalf("repeat revoke by same actor must succeed while save unavailable: %v", err)
127		}
128	
129		// 另一名有权的内部使用者在更晚时刻确认：同样成功，且撤回时间不被更新
130		// 到本次调用时刻，接收方、范围、有效期保持原样。
131		clk.t = later.Add(3 * time.Hour)
132		if err := s.Revoke(doc2, p.ID, a1.ID); err != nil {
133			t.Fatalf("repeat revoke by another internal actor must succeed: %v", err)
134		}
135		again, err := s.GetAuthorization(doc2, p.ID, a1.ID)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if again.RevokedAt == nil || !again.RevokedAt.Equal(firstRevokeAt) {
140			t.Fatalf("repeat confirmation changed revocation time: got %v, want %v",
141				again.RevokedAt, firstRevokeAt)
142		}
143		if again.ReceiverID != first.ReceiverID ||
144			!reflect.DeepEqual(again.Scopes, firstScope) ||
145			!reflect.DeepEqual(again.Selections, firstSels) ||
146			!again.StartsAt.Equal(first.StartsAt) || !again.ExpiresAt.Equal(first.ExpiresAt) {
147			t.Fatalf("repeat confirmation changed receiver/scope/window:\nfirst: %+v\nafter: %+v",
148				first, again)
149		}
150	
151		// 按患者查看审计：这条授权的撤回事件仍只有首次那一条，身份与时间不变。
152		audit, err := s.AuditEvents(doc2, p.ID)
153		if err != nil {
154			t.Fatal(err)
155		}
156		var revokeEvents []AuditEvent
157		for _, ev := range audit {
158			if ev.Action == ActionRevoked {
159				revokeEvents = append(revokeEvents, ev)
160			}
161		}
162		if len(revokeEvents) != 1 {
163			t.Fatalf("revoke events = %+v, want exactly the first one", revokeEvents)
164		}
165		if ev := revokeEvents[0]; ev.ObjectID != a1.ID || ev.ActorID != doc.ID ||
166			!ev.OccurredAt.Equal(firstRevokeAt) {
167			t.Fatalf("first revoke event altered by confirmation: %+v", ev)
168		}
169	
170		// 既有身份与归属规则不变：接收方不能撤回；不存在/跨患者仍明确失败，
171		// “已撤回”不能让这些请求成功，也与保存条件无关。
172		if err := s.Revoke(rcv, p.ID, a1.ID); !errors.Is(err, ErrAccessDenied) {
173			t.Fatalf("receiver revoke err = %v, want ErrAccessDenied", err)
174		}
175		if err := s.Revoke(doc, p.ID, "auth_missing"); !errors.Is(err, ErrNotFound) {
176			t.Fatalf("revoke missing authorization while save blocked: err = %v, want ErrNotFound", err)
177		}
178		if err := s.Revoke(doc, p2.ID, a1.ID); !errors.Is(err, ErrMismatchedPatient) {
179			t.Fatalf("cross-patient revoke while save blocked: err = %v, want ErrMismatchedPatient", err)
180		}
181	
182		// 已撤回授权继续失效：a1 整类撤回后，接收方只能靠独立生效的 a2 读到 d1。
183		res, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
184		if err != nil {
185			t.Fatalf("receiver read with the independent limited grant: %v", err)
186		}
187		if len(res.Records) != 1 || res.Records[0].RecordID != d1 {
188			t.Fatalf("read after repeat confirmations = %+v, want only d1 via the other grant", res.Records)
189		}
190		// 绑定 a1 的交换取包仍被拒，重复确认不改写既有交换权限。
191		if delivery, err := s.FetchPackage(rcv, exch.ID); !errors.Is(err, ErrAccessDenied) ||
192			delivery.Digest != "" || len(delivery.Package.Records) != 0 {
193			t.Fatalf("fetch bound to revoked auth: delivery=%+v err=%v", delivery, err)
194		}
195	
196		// ---- 尚未撤回的 a2 在保存不可用时首次撤回：必须报保存错误 ----
197		if err := s.Revoke(doc, p.ID, a2.ID); err == nil {
198			t.Fatal("first revoke must fail when local save is unavailable")
199		} else if errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrNotFound) ||
200			errors.Is(err, ErrMismatchedPatient) || errors.Is(err, ErrInvalidArgument) ||
201			errors.Is(err, ErrDeactivated) || errors.Is(err, ErrConflict) {
202			t.Fatalf("save failure surfaced as a business error: %v", err)
203		}
204		gotA2, err := s.GetAuthorization(doc, p.ID, a2.ID)
205		if err != nil {
206			t.Fatal(err)
207		}
208		if gotA2.RevokedAt != nil {
209			t.Fatalf("failed first revoke must not mark authorization revoked: %+v", gotA2)
210		}
211		// 失败尝试不能提前禁止原授权允许的读取。
212		res, err = s.Read(rcv, p.ID, e.ID, Diagnosis)
213		if err != nil {
214			t.Fatalf("failed revoke must not cut access early: %v", err)
215		}
216		if len(res.Records) != 1 || res.Records[0].RecordID != d1 {
217			t.Fatalf("read after failed revoke = %+v, want d1 still visible", res.Records)
218		}
219		// 不新增撤回事件。
220		auditNow, err := s.AuditEvents(doc, p.ID)
221		if err != nil {
222			t.Fatal(err)
223		}
224		if !reflect.DeepEqual(auditNow, audit) {
225			t.Fatalf("failed first revoke changed audit:\nbefore: %+v\nafter:  %+v", audit, auditNow)
226		}
227		// 失败不能留下半截临时文件。
228		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
229			t.Fatalf("failed save left a temp file: %v", statErr)
230		}
231		// 此前失败的尝试不能成为直接成功的依据：保存仍不可用时再次提交仍失败。
232		if err := s.Revoke(doc2, p.ID, a2.ID); err == nil {
233			t.Fatal("retry while save still unavailable must not succeed on the strength of a failed attempt")
234		}
235		if gotA2, err := s.GetAuthorization(doc, p.ID, a2.ID); err != nil || gotA2.RevokedAt != nil {
236			t.Fatalf("retry after failed attempt must leave authorization unrevoked: %+v err=%v", gotA2, err)
237		}
238	
239		// ---- 恢复保存条件：随后提交才真正撤回，记录本次实际成功的时间与身份 ----
240		if err := s.Close(); err != nil {
241			t.Fatal(err)
242		}
243		if err := os.Remove(dataPath); err != nil {
244			t.Fatalf("unblock data path: %v", err)
245		}
246		if err := os.Rename(backupPath, dataPath); err != nil {
247			t.Fatalf("restore data file: %v", err)
248		}
249		s = open()
250		t.Cleanup(func() { _ = s.Close() })
251	
252		// 重开后：a1 仍是首次撤回的结果与唯一事件；a2 仍未撤回。
253		reloadedA1, err := s.GetAuthorization(doc, p.ID, a1.ID)
254		if err != nil {
255			t.Fatal(err)
256		}
257		if reloadedA1.RevokedAt == nil || !reloadedA1.RevokedAt.Equal(firstRevokeAt) {
258			t.Fatalf("a1 after reopen: %+v", reloadedA1)
259		}
260		reloadedA2, err := s.GetAuthorization(doc, p.ID, a2.ID)
261		if err != nil {
262			t.Fatal(err)
263		}
264		if reloadedA2.RevokedAt != nil {
265			t.Fatalf("a2 must remain unrevoked after reopen: %+v", reloadedA2)
266		}
267	
268		secondRevokeAt := clk.t.Add(5 * time.Hour)
269		clk.t = secondRevokeAt
270		if err := s.Revoke(doc2, p.ID, a2.ID); err != nil {
271			t.Fatalf("revoke a2 after save recovered: %v", err)
272		}
273		doneA2, err := s.GetAuthorization(doc2, p.ID, a2.ID)
274		if err != nil {
275			t.Fatal(err)
276		}
277		if doneA2.RevokedAt == nil || !doneA2.RevokedAt.Equal(secondRevokeAt) {
278			t.Fatalf("a2 revocation time = %v, want %v", doneA2.RevokedAt, secondRevokeAt)
279		}
280	
281		// 最终审计：a1 的撤回事件仍属首次操作（doc、firstRevokeAt），
282		// a2 新增一条属于实际成功操作（doc2、secondRevokeAt）的事件。
283		finalAudit, err := s.AuditEvents(doc, p.ID)
284		if err != nil {
285			t.Fatal(err)
286		}
287		var finalRevokes []AuditEvent
288		for _, ev := range finalAudit {
289			if ev.Action == ActionRevoked {
290				finalRevokes = append(finalRevokes, ev)
291			}
292		}
293		if len(finalRevokes) != 2 {
294			t.Fatalf("final revoke events = %+v, want 2", finalRevokes)
295		}
296		byObject := map[ID]AuditEvent{}
297		for _, ev := range finalRevokes {
298			byObject[ev.ObjectID] = ev
299		}
300		if ev := byObject[a1.ID]; ev.ActorID != doc.ID || !ev.OccurredAt.Equal(firstRevokeAt) {
301			t.Fatalf("a1 revoke event must stay the first one: %+v", ev)
302		}
303		if ev := byObject[a2.ID]; ev.ActorID != doc2.ID || !ev.OccurredAt.Equal(secondRevokeAt) {
304			t.Fatalf("a2 revoke event must record the actual successful operation: %+v", ev)
305		}
306	
307		// 两条授权都撤回后：接收方读取被拒，但其他患者/档案状态不受影响。
308		if _, err := s.Read(rcv, p.ID, e.ID, Diagnosis); !errors.Is(err, ErrAccessDenied) {
309			t.Fatalf("read after both revokes: err = %v, want ErrAccessDenied", err)
310		}
311	}
